// 1. Obtener todos los mensajes que devolvió Supabase
let mensajes = $input.all();

// 2. Si no hay mensajes, detenemos el flujo
if (mensajes.length === 0) return [];

// 3. Ordenar TODOS los mensajes por su 'id' de mayor a menor (del más nuevo al más viejo)
mensajes.sort((a, b) => b.json.id - a.json.id);

// 4. Recortar solo los primeros 15 de esa lista ordenada (los 15 más recientes)
let ultimos15 = mensajes.slice(0, 15);

// 5. Invertir esos 15 para que queden en orden cronológico (del más antiguo al más nuevo para que la IA entienda la charla)
ultimos15.reverse();

// 6. Formatear el texto limpio para el LLM evaluador
let contextoTexto = "";

ultimos15.forEach(item => {
  const tipoMensaje = item.json.message.type;
  let contenido = item.json.message.content;
  let emisor = "";

  // Clasificamos quién está hablando
  if (tipoMensaje === 'human_manual') {
    emisor = "Ejecutivo Humano";
  } else if (tipoMensaje === 'ai') {
    emisor = "Polaris (IA)";
  } else if (tipoMensaje === 'human') {
    emisor = "Cliente";
    // Limpiamos el prefijo sucio para ahorrar tokens y dar claridad
    contenido = contenido.replace("=Mensaje_Cliente: ", "").trim();
  }

  // Armamos el guion de la obra
  if (emisor !== "") {
    contextoTexto += `${emisor}: ${contenido}\n`;
  }
});

// 7. Entregar el paquete final
return {
  session_id: $('Webhook').first().json.body.record.session_id,
  contexto_formateado: contextoTexto
};
